const ITEM_DESCRIPTION_LIMIT=140;
let itemOpener=null;
function prepareItemDescriptionField(){const field=$('#item-form').elements.description;field.id='item-description';field.maxLength=ITEM_DESCRIPTION_LIMIT;let meta=$('#item-description-meta');if(!meta){meta=document.createElement('span');meta.className='field-meta';meta.id='item-description-meta';meta.innerHTML='<span>Shown on the customer menu.</span><output id="item-description-count" for="item-description"></output>';field.after(meta);field.setAttribute('aria-describedby',meta.id)}return field}
function updateItemDescriptionCount(){const field=prepareItemDescriptionField(),count=$('#item-description-count');count.value=`${field.value.length} / ${ITEM_DESCRIPTION_LIMIT}`;field.setCustomValidity(field.value.length>ITEM_DESCRIPTION_LIMIT?`Keep the description to ${ITEM_DESCRIPTION_LIMIT} characters or fewer.`:'')}
function updateItemOptionSummary(item){const summary=$('#item-options-summary'),button=$('#manage-item-options');if(!item){summary.textContent='Save this item before adding item-specific choices.';button.textContent='Save item first';button.disabled=true;return}const groups=groupsForItem(item),own=groups.filter(group=>group.scope==='item').length;summary.textContent=groups.length?`${groups.length} set${groups.length===1?'':'s'} apply · ${own} specific to this item`:'No choices apply yet.';button.textContent='Configure';button.disabled=false}
function openItem(id=null){itemOpener=document.activeElement;editingId=id;const i=items.find(x=>x.id===id),f=$('#item-form');f.reset();f.elements.name.setCustomValidity('');f.elements.description.setCustomValidity('');photoVersion++;pendingPhoto=i?.photo||null;pendingPhotoMeta=i?{photoOriginalKey:i.photoOriginalKey||'',photoOptimized:Boolean(i.photoOptimized),photoWidth:i.photoWidth,photoHeight:i.photoHeight,photoBytes:i.photoBytes}:{};$('#photo-error').textContent='';$('#save-item').disabled=false;updatePhotoPreview();f.elements.category.innerHTML=categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');$('#dialog-title').textContent=i?'Edit menu item':'Add a menu item';$('#save-item').textContent=i?'Save changes':'Add item';$('#delete-item').hidden=!i;if(i){['name','description','price','category'].forEach(k=>f.elements[k].value=i[k]||'');f.elements.available.checked=i.available;f.elements.hidden.checked=Boolean(i.hidden)}else if(categories.includes(active))f.elements.category.value=active;updateItemDescriptionCount();updateItemOptionSummary(i);$('#item-dialog').showModal();f.elements.name.focus()}
