function orderLocation(order){const location=order.fulfillmentType==='table'?`Table ${order.tableNumber||'—'}`:'Pickup';return`${location}${order.customerLabel?` · ${order.customerLabel}`:''}`}
function itemCount(order){return order.items.reduce((sum,item)=>sum+(Number(item.quantity)||0),0)}
function orderTotal(order){return Number.isInteger(order.subtotalMinor)?order.subtotalMinor:order.items.reduce((sum,item)=>sum+(Number(item.lineTotalMinor)||0),0)}
function formatMoney(minor){return money.format((Number(minor)||0)/100).replace('PHP','₱')}
function ageMinutes(order){return Math.max(0,Math.floor((Date.now()-new Date(order.createdAt).getTime())/60000)||0)}
function elapsedLabel(order){const minutes=ageMinutes(order);if(minutes<1)return 'just now';if(minutes<60)return `${minutes} min ago`;const hours=Math.floor(minutes/60);return `${hours} hr${hours===1?'':'s'} ago`}
function statusLabel(status){return ({received:'Received',preparing:'Received',ready:'Received',completed:'Completed',cancelled:'Cancelled'})[status]||status}
function eventList(order){if(Array.isArray(order.events)&&order.events.length)return order.events;return [{status:'received',at:order.createdAt,label:'Order received'},...(order.status!=='received'?[{status:order.status,at:order.updatedAt||order.createdAt,label:`Marked ${statusLabel(order.status).toLowerCase()}`}]:[])]}
async function setOrderStatus(order,status,label,{refreshDetail=true}={}){try{await dataService.transitionOrder({orderId:order.id,expectedStatus:order.status,nextStatus:status,handoffToken:status==='completed'?order.verificationToken:null});await syncOrders();if(refreshDetail&&$('#order-detail-dialog').open)openOrderDetail(order.id);announce(`Order #${order.orderNumber} ${label.toLowerCase()}`);return true}catch(error){announce(error.message||'The order could not be updated');return false}}
const orderCompletionLabel=()=>businessExperience.serviceMode==='quick'?'Mark paid':'Mark served';
const completedHistoryLabel=()=>businessExperience.serviceMode==='quick'?'Paid':'Served';
async function completeOrder(order){if(order.status==='received'){const moved=await setOrderStatus(order,'preparing','Accepted',{refreshDetail:false});if(!moved)return;order=orders.find(item=>String(item.id)===String(order.id))||{...order,status:'preparing'}}if(order.status==='preparing'){const moved=await setOrderStatus(order,'ready','Ready',{refreshDetail:false});if(!moved)return;order=orders.find(item=>String(item.id)===String(order.id))||{...order,status:'ready'}}if(order.status==='ready')await setOrderStatus(order,'completed',businessExperience.serviceMode==='quick'?'Marked paid':'Marked served',{refreshDetail:false});if($('#order-detail-dialog').open)$('#order-detail-dialog').close()}
function orderCard(order,actionLabel){const age=ageMinutes(order),priority=age>=15||order.status==='received'&&age>=5,options=itemCount(order);return `<article class="service-order-card${priority?' priority':''}${order.status==='received'?' newly-received':''}"><button type="button" class="service-order-detail" data-order-id="${esc(String(order.id))}" aria-label="View order ${esc(String(order.orderNumber))} details"><span class="service-order-top"><strong>#${esc(String(order.orderNumber))}</strong><time>${esc(elapsedLabel(order))}</time></span><b>${esc(orderLocation(order))}</b><small>${options} item${options===1?'':'s'} · ${esc(formatMoney(orderTotal(order)))}</small>${order.paymentMethod==='counter'?'<span class="order-has-note">Pay at counter</span>':''}${order.notes?'<span class="order-has-note">Has order note</span>':''}</button><button type="button" class="service-order-action" data-order-action="${esc(String(order.id))}">${actionLabel}</button></article>`}
function historyCard(order){const timestamp=new Date(order.updatedAt||order.createdAt).toLocaleString([],{dateStyle:'medium',timeStyle:'short'});return `<button type="button" class="history-order-card" data-order-id="${esc(String(order.id))}"><span><strong>#${esc(String(order.orderNumber))}</strong><small>${esc(orderLocation(order))} · ${itemCount(order)} item${itemCount(order)===1?'':'s'} · ${esc(timestamp)}</small></span><span><em class="order-state ${esc(order.status)}">${order.status==='completed'?completedHistoryLabel():statusLabel(order.status)}</em><b>${esc(formatMoney(orderTotal(order)))}</b></span></button>`}
async function renderTableRequests(){const tab=$('#table-requests-tab');tab.hidden=!tableSessionService;if(!tableSessionService)return;await tableSessionService.refresh().catch(()=>[]);const sessions=tableSessionService.sessions.filter(session=>['pending','active','bill_requested','inactivity_warning'].includes(session.status)),occupied=sessions.filter(session=>session.status!=='pending'),pendingCount=sessions.reduce((count,session)=>count+(session.status==='pending'?1:0)+(session.joinRequests||[]).filter(request=>request.status==='pending').length,0),occupiedBadge=$('#table-request-count'),openTab=Boolean(businessExperience.serviceProfile.layers.openOrderTab);let pendingBadge=$('#table-pending-count');if(!pendingBadge){pendingBadge=document.createElement('span');pendingBadge.id='table-pending-count';pendingBadge.className='table-pending-count';tab.append(pendingBadge)}occupiedBadge.classList.add('stage-count');occupiedBadge.textContent=occupied.length;occupiedBadge.setAttribute('aria-label',`${occupied.length} occupied table${occupied.length===1?'':'s'}`);$('#occupied-table-count').textContent=occupied.length;pendingBadge.textContent=pendingCount;pendingBadge.hidden=pendingCount===0;pendingBadge.setAttribute('aria-label',`${pendingCount} pending request${pendingCount===1?'':'s'}`);$('#table-request-list').innerHTML=Array.from({length:6},(_,index)=>{const table=String(index+1),session=sessions.find(item=>item.table===table);if(!session)return`<article class="table-card available"><div><span class="table-card-number">Table ${table}</span><strong class="table-card-status">Available</strong></div><p>Ready for new guests</p></article>`;const waiting=session.status==='pending',warning=session.status==='inactivity_warning',joins=(session.joinRequests||[]).filter(request=>request.status==='pending').length,guestCount=Number(session.guestCount)||1,closeAttribute=openTab?'data-paid-table':'data-clean-table',closeLabel=openTab?'Customer paid':'Table cleaned';return`<article class="table-card ${waiting?'pending':'occupied'}"><div><span class="table-card-number">Table ${table}</span><strong class="table-card-status">${waiting?'Request pending':warning?'Inactivity warning':'Occupied'}</strong></div><p>${esc(session.participants[0]?.name||'Guest')} · ${guestCount} guest${guestCount===1?'':'s'}${joins?` · ${joins} waiting`:''}${warning?' · confirm before closing':''}</p><button type="button" class="table-card-action" ${waiting?`data-accept-table="${esc(session.id)}"`:`${closeAttribute}="${esc(session.id)}"`}>${waiting?'Accept table request':closeLabel}</button></article>`}).join('')}
function renderOrders(){
 const received=orders.filter(order=>ACTIVE_ORDER_STATES.includes(order.status)).sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt)),history=orders.filter(order=>HISTORY_ORDER_STATES.includes(order.status)).sort((a,b)=>new Date(b.updatedAt||b.createdAt)-new Date(a.updatedAt||a.createdAt));
 $('#active-order-count').textContent=received.length;$('#history-order-count').textContent=history.length;$('#show-order-history').setAttribute('aria-label',`Open order history, ${history.length} item${history.length===1?'':'s'}`);$('#received-order-count').textContent=received.length;
 $('#received-order-list').innerHTML=received.map(order=>orderCard(order,orderCompletionLabel())).join('');$('#history-order-list').innerHTML=history.map(historyCard).join('');
 $('#received-order-empty').hidden=received.length>0;$('#history-order-empty').hidden=history.length>0;
 const receivedCount=received.length,indicator=$('#new-order-indicator');indicator.hidden=receivedCount===0;indicator.lastChild.textContent=receivedCount===1?'1 new order':`${receivedCount} new orders`;
 const alert=$('.nav-alert');alert.textContent=orders.filter(order=>ACTIVE_ORDER_STATES.includes(order.status)).length;alert.hidden=!Number(alert.textContent);
 const preview=$('.order-preview-list'),active=orders.filter(order=>ACTIVE_ORDER_STATES.includes(order.status)).sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt)).slice(0,4);preview.innerHTML=active.length?active.map(order=>`<button type="button" data-order-select="${esc(String(order.id))}"><span class="order-number">#${esc(String(order.orderNumber))}</span><span><strong>${esc(orderLocation(order))}</strong><small>${itemCount(order)} items · ${esc(formatMoney(orderTotal(order)))}</small></span><span class="order-state ${esc(order.status)}">${statusLabel(order.status)}</span><time>${ageMinutes(order)} min</time></button>`).join(''):'<p class="dashboard-order-empty">No active demo orders.</p>';
 const activeMetric=$('.metric-card strong');if(activeMetric)activeMetric.textContent=orders.filter(order=>ACTIVE_ORDER_STATES.includes(order.status)).length;
 renderTableRequests();
 icons($('#live-orders-view'));icons($('#order-history-view'));icons(preview);
}
function showOrderStage(stage,{focus=false}={}){for(const name of ['received','requests'])$(`#${name==='requests'?'table-requests':name+'-orders'}-panel`).hidden=name!==stage;document.querySelectorAll('[data-order-stage]').forEach(button=>{const selected=button.dataset.orderStage===stage;button.classList.toggle('active',selected);button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1});if(focus)requestAnimationFrame(()=>document.querySelector(`[data-order-stage="${stage}"]`)?.focus())}
function openOrderDetail(id){
 const order=orders.find(item=>String(item.id)===String(id));if(!order)return;selectedOrderId=String(order.id);const dialog=$('#order-detail-dialog');
 $('#order-detail-title').textContent=`#${order.orderNumber} · ${orderLocation(order)}`;$('#order-detail-time').textContent=`Created ${new Date(order.createdAt).toLocaleString()} · ${elapsedLabel(order)}`;
 const state=$('#order-detail-state');state.textContent=statusLabel(order.status);state.className=`order-state ${order.status}`;$('#order-detail-fulfillment').textContent=orderLocation(order);$('#order-detail-count').textContent=`${itemCount(order)} item${itemCount(order)===1?'':'s'}`;
 const age=ageMinutes(order),ageAlert=$('#order-age-alert');ageAlert.hidden=!(ACTIVE_ORDER_STATES.includes(order.status)&&age>=15);ageAlert.textContent=`This order has been open for ${age} minutes.`;
 $('#order-detail-lines').innerHTML=order.items.map(item=>{const choices=Array.isArray(item.selectedOptions)?item.selectedOptions.filter(Boolean):[];return `<div><span><strong>${Number(item.quantity)||0} × ${esc(String(item.name||'Menu item'))}</strong>${choices.length?`<small>${choices.map(choice=>esc(typeof choice==='string'?choice:String(choice.name||choice.label||choice.value||''))).join(' · ')}</small>`:''}</span><b>${esc(formatMoney(Number.isInteger(item.lineTotalMinor)?item.lineTotalMinor:(Number(item.unitPriceMinor)||0)*(Number(item.quantity)||0)))}</b></div>`}).join('')+`<div class="order-total"><span>Total</span><strong>${esc(formatMoney(orderTotal(order)))}</strong></div>`;
 $('#order-note-section').hidden=!order.notes;$('#order-detail-note').textContent=order.notes||'';
 const final=HISTORY_ORDER_STATES.includes(order.status),advance=$('#advance-order'),admin=!accessContext||['owner','admin'].includes(accessContext.role),permission=accessContext?.permissions||{};
 const canAdvance=admin||(order.status==='received'?(permission.acceptOrders&&permission.prepareOrders):(permission.markReady&&permission.completeOrders));
 $('#cancel-order').hidden=final||(!admin&&!permission.cancelOrders);advance.hidden=final||!canAdvance;advance.disabled=false;advance.textContent=orderCompletionLabel();
 if(!dialog.open)dialog.showModal();requestAnimationFrame(()=>$('#close-order-detail').focus());
}
async function syncOrders({announceNew=false}={}){const before=new Set(orders.map(order=>String(order.id))),next=await readOrders(),newReceived=next.filter(order=>!before.has(String(order.id))&&order.status==='received');orders=next;renderOrders();if(announceNew&&newReceived.length){announce(`${newReceived.length} new order${newReceived.length===1?'':'s'} received`);if($('#order-sound-toggle').checked)playOrderTone()}}
function playOrderTone(){try{const AudioContext=window.AudioContext||window.webkitAudioContext,context=new AudioContext(),tone=context.createOscillator(),gain=context.createGain();tone.frequency.value=660;gain.gain.setValueAtTime(.06,context.currentTime);gain.gain.exponentialRampToValueAtTime(.001,context.currentTime+.18);tone.connect(gain).connect(context.destination);tone.start();tone.stop(context.currentTime+.18)}catch{}}
orders=await readOrders();renderOrders();
async function handleOrderBoardClick(e){const tableAction=e.target.closest('[data-accept-table],[data-clean-table],[data-paid-table]');if(tableAction&&tableSessionService){tableAction.disabled=true;try{if(tableAction.dataset.acceptTable){await tableSessionService.accept(tableAction.dataset.acceptTable);announce('Table accepted')}else{const sessionId=tableAction.dataset.paidTable||tableAction.dataset.cleanTable,session=tableSessionService.sessions.find(item=>String(item.id)===sessionId),tableOrders=orders.filter(order=>order.fulfillmentType==='table'&&String(order.tableNumber)===String(session?.table)&&ACTIVE_ORDER_STATES.includes(order.status));for(const order of tableOrders){await completeOrder(order);if(ACTIVE_ORDER_STATES.includes((orders.find(item=>String(item.id)===String(order.id))||order).status))throw new Error(`Order #${order.orderNumber} could not be archived`)}if(tableAction.dataset.paidTable){await tableSessionService.markPaid(sessionId);announce('Customer payment confirmed · orders saved to history')}else{await tableSessionService.clean(sessionId);announce(`Table marked available${tableOrders.length?` · ${tableOrders.length} order${tableOrders.length===1?'':'s'} saved to history`:''}`)}await syncOrders()}}catch(error){announce(error.message||'The table could not be updated');tableAction.disabled=false}finally{await renderTableRequests()}return}const action=e.target.closest('[data-order-action]');if(action){const order=orders.find(item=>String(item.id)===action.dataset.orderAction);if(!order)return;action.disabled=true;try{await completeOrder(order)}finally{if(action.isConnected)action.disabled=false}return}const detail=e.target.closest('[data-order-id]');if(detail)openOrderDetail(detail.dataset.orderId)}
$('#live-orders-view').onclick=handleOrderBoardClick;$('#order-history-view').onclick=handleOrderBoardClick;
document.querySelectorAll('[data-order-stage]').forEach(button=>{button.onclick=()=>showOrderStage(button.dataset.orderStage);button.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-order-stage]:not([hidden])')],index=tabs.indexOf(button),next=e.key==='ArrowRight'?(index+1)%tabs.length:(index-1+tabs.length)%tabs.length;showOrderStage(tabs[next].dataset.orderStage,{focus:true})}});tableSessionService?.subscribe(renderTableRequests);
$('#show-order-history').onclick=()=>{$('#live-orders-view').hidden=true;$('#order-history-view').hidden=false;$('#show-order-history').setAttribute('aria-pressed','true');requestAnimationFrame(()=>$('#hide-order-history').focus())};
$('#hide-order-history').onclick=()=>{$('#order-history-view').hidden=true;$('#live-orders-view').hidden=false;$('#show-order-history').setAttribute('aria-pressed','false');requestAnimationFrame(()=>$('#show-order-history').focus())};
$('.order-preview-list').onclick=e=>{const button=e.target.closest('[data-order-select]');if(button){showDashboardPage('orders');openOrderDetail(button.dataset.orderSelect)}};
$('#close-order-detail').onclick=()=>$('#order-detail-dialog').close();$('#order-detail-dialog').addEventListener('click',e=>{if(e.target===$('#order-detail-dialog'))$('#order-detail-dialog').close()});
$('#advance-order').onclick=()=>{const order=orders.find(item=>String(item.id)===selectedOrderId);if(order)completeOrder(order)};
$('#cancel-order').onclick=()=>{const order=orders.find(item=>String(item.id)===selectedOrderId);if(!order)return;$('#cancel-order-title').textContent=`Cancel order #${order.orderNumber}?`;$('#cancel-order-dialog').showModal();requestAnimationFrame(()=>$('#confirm-cancel-order').focus())};
$('#confirm-cancel-order').onclick=()=>{const order=orders.find(item=>String(item.id)===selectedOrderId);$('#cancel-order-dialog').close();if(order)setOrderStatus(order,'cancelled','Order cancelled')};
$('#refresh-orders').onclick=async()=>{await syncOrders();announce(`${dataService.mode==='demo'?'Device-local':'Backend'} orders refreshed`)};
$('#order-sound-toggle').checked=localStorage.getItem('qrk_demo_order_sound_v1')==='on';$('#order-sound-toggle').onchange=e=>{localStorage.setItem('qrk_demo_order_sound_v1',e.target.checked?'on':'off');announce(`New-order sound ${e.target.checked?'on':'off'} for this browser`)};
dataService.subscribe({onOrdersChanged:()=>syncOrders({announceNew:true}),onStoreChanged:async()=>updateStoreStatus(await readStoreOpen())});
